#include <Servo.h>

// --- Пины ---
const int trigPin = 9;
const int echoPin = 10;
const int ledPin = 8;
const int servoPin = 6;

// --- Порог обнаружения (в сантиметрах) ---
const int threshold = 20;   // Если объект ближе 20 см — срабатывает

Servo myServo;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);
  myServo.attach(servoPin);
  Serial.begin(9600);       // Для отладки
}

void loop() {
  long duration;
  int distance;

  // --- Измерение расстояния ---
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  duration = pulseIn(echoPin, HIGH);
  distance = duration * 0.034 / 2;   // Перевод в сантиметры

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // --- Логика ---
  if (distance > 0 && distance < threshold) {
    // Объект обнаружен — включаем светодиод
    digitalWrite(ledPin, HIGH);

    // Сервопривод: 5 секунд в одну сторону (0° → 180°)
    for (int angle = 0; angle <= 180; angle++) {
      myServo.write(angle);
      delay(5000 / 180);   // ≈ 27.7 мс на градус → всего 5 секунд
    }

    // Сервопривод: 5 секунд в другую сторону (180° → 0°)
    for (int angle = 180; angle >= 0; angle--) {
      myServo.write(angle);
      delay(5000 / 180);   // ≈ 27.7 мс на градус → всего 5 секунд
    }

  } else {
    // Объект не обнаружен — выключаем светодиод и останавливаем сервопривод
    digitalWrite(ledPin, LOW);
    myServo.write(90);     // Возврат в среднее положение (или можно myServo.detach())
  }

  delay(100);              // Небольшая пауза для стабильности
}
